// WorkerNode1HL only -- control plane scenarios removed per request.
// Nexacore scenarios (404 / application down) added to the rotation to match
// the two dedicated Master SOPs already in the KB for this app (KB0000034 --
// static-file-serving 404 fix, KB0000039 -- port 8080 service recovery), and
// phrased to match how these incidents actually read historically in the DB
// (see INC0001460/INC0001143 for the down-scenario wording) so RAG retrieval
// matches the same way it does for a real human-filed ticket.
const incidentList = [
  {
    text: "CPU Utilization on Workernode1HL is 100%",
    targetCi: "WorkerNode1HL",
    priority: "P4",
    impact: "TEAM",
    urgency: "LOW"
  },
  {
    text: "Memory utilization on Workernode1HL is 100%",
    targetCi: "WorkerNode1HL",
    priority: "P4",
    impact: "TEAM",
    urgency: "LOW"
  },
  {
    text: "Nexacore Application is throwing 404 error. Getting below error. HTTP 404 Not Found - The requested resource (index.html) could not be found on this server. URL: http://workernode1hl:8080/",
    targetCi: "WorkerNode1HL",
    priority: "P2",
    impact: "DEPARTMENT",
    urgency: "HIGH"
  },
  {
    text: "Nexacore application is down . connection refused on port 8080",
    targetCi: "WorkerNode1HL",
    priority: "P2",
    impact: "DEPARTMENT",
    urgency: "HIGH"
  }
];

// Rotate sequentially every execution based on timestamp interval
const index = Math.floor(Date.now() / (5 * 60 * 1000)) % incidentList.length;
const selected = incidentList[index];

return [{
  json: {
    shortDescription: selected.text,
    description: selected.text,
    configurationItem: selected.targetCi,
    priority: selected.priority,
    impact: selected.impact,
    urgency: selected.urgency,
    callerName: "n8n Telemetry Engine",
    generatedAt: new Date().toISOString()
  }
}];

const res = $input.first().json;
const body = res.body || res;

return [{
  json: {
    status: 'SUCCESS',
    incidentNumber: body.number || body.id,
    title: body.shortDescription,
    configurationItem: body.configurationItem || body.configurationItemName,
    priority: body.priority,
    state: body.state,
    createdAt: body.createdAt || new Date().toISOString(),
    message: `[n8n] Successfully created ${body.priority} incident ${body.number || body.id}: "${body.shortDescription}" on ${body.configurationItem || body.configurationItemName}`
  }
}];
